import { createWorkspace, teardownWorkspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { writeFile } from "fs/promises";
import { join } from "path";

async function main() {
  const agentNames = ["pool-agent-1", "pool-agent-2", "pool-agent-3", "pool-agent-4"];
  const projectDir = "/home/user/ws-pool";
  const poolJsonPath = join(projectDir, "pool.json");

  console.log("Provisioning workspaces in parallel...");

  const workspaces = await Promise.all(
    agentNames.map((name) =>
      createWorkspace(name, {
        ttl: { days: 1 },
        credentials: { role: "Editor" },
      })
    )
  );

  console.log("Workspaces created. Initializing with init.txt...");

  try {
    await Promise.all(
      workspaces.map(async (ws, index) => {
        const agentName = agentNames[index];
        const s3 = new S3Client({
          endpoint: "https://t3.storage.dev",
          region: "auto",
          credentials: {
            accessKeyId: ws.credentials.accessKeyId,
            secretAccessKey: ws.credentials.secretAccessKey,
            sessionToken: ws.credentials.sessionToken,
          },
        });

        await s3.send(
          new PutObjectCommand({
            Bucket: ws.bucket,
            Key: "init.txt",
            Body: agentName,
          })
        );
      })
    );

    console.log("Initialization complete. Writing pool.json...");

    const summary = workspaces.map((ws, index) => ({
      name: agentNames[index],
      bucket: ws.bucket,
    }));

    await writeFile(poolJsonPath, JSON.stringify(summary, null, 2));
    console.log(`Summary written to ${poolJsonPath}`);

  } catch (error) {
    console.error("An error occurred during provisioning or initialization:", error);
    // Even if initialization fails, we should try to teardown what we created
    // But the requirements say "Errors during creation MUST cause the script to exit non-zero."
    // And "The script MUST exit with status code 0 on success."
    // We will attempt teardown anyway to be resilient.
  } finally {
    console.log("Tearing down workspaces...");
    const results = await Promise.allSettled(
      workspaces.map((ws) => teardownWorkspace(ws.name))
    );

    let teardownFailed = false;
    results.forEach((result, index) => {
      if (result.status === "rejected") {
        console.error(`Failed to teardown workspace ${agentNames[index]}:`, result.reason);
        teardownFailed = true;
      } else {
        console.log(`Successfully tore down workspace ${agentNames[index]}`);
      }
    });

    if (teardownFailed) {
      // If teardown failed, we might still want to exit non-zero depending on interpretation
      // but the main success path is what matters most.
    }
  }
}

main().catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});

