import { createWorkspace, teardownWorkspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { writeFile } from "fs/promises";
import { join } from "path";

async function main() {
  const agentNames = ["pool-agent-1", "pool-agent-2", "pool-agent-3", "pool-agent-4"];
  const projectDir = "/home/user/ws-pool";
  const poolJsonPath = join(projectDir, "pool.json");

  console.log("Provisioning workspaces in parallel...");

  const results = await Promise.all(
    agentNames.map((name) =>
      createWorkspace(name, {
        ttl: { days: 1 },
        credentials: { role: "Editor" },
      })
    )
  );

  // Check for errors in creation
  for (const res of results) {
    if (res.error) {
      console.error("Failed to create workspace:", res.error);
      process.exit(1);
    }
  }

  // At this point we know all data exists
  const workspaces = results.map(res => res.data!);

  console.log("Workspaces created. Initializing with init.txt...");

  try {
    await Promise.all(
      workspaces.map(async (ws, index) => {
        const agentName = agentNames[index];

        if (!ws.credentials) {
            throw new Error(`No credentials returned for workspace ${agentName}`);
        }

        const s3 = new S3Client({
          endpoint: "https://t3.storage.dev",
          region: "auto",
          credentials: {
            accessKeyId: ws.credentials.accessKeyId,
            secretAccessKey: ws.credentials.secretAccessKey,
          },
        });

        await s3.send(
          new PutObjectCommand({
            Bucket: ws.bucket,
            Key: "init.txt",
            Body: agentName,
          })
        );
      })
    );

    console.log("Initialization complete. Writing pool.json...");

    const summary = workspaces.map((ws, index) => ({
      name: agentNames[index],
      bucket: ws.bucket,
    }));

    await writeFile(poolJsonPath, JSON.stringify(summary, null, 2));
    console.log(`Summary written to ${poolJsonPath}`);

  } catch (error) {
    console.error("An error occurred during initialization:", error);
    throw error; // Rethrow to ensure teardown runs but script exits non-zero if initialization failed
  } finally {
    console.log("Tearing down workspaces...");
    const teardownResults = await Promise.allSettled(
      workspaces.map((ws) => teardownWorkspace(ws))
    );

    let teardownFailed = false;
    teardownResults.forEach((result, index) => {
      if (result.status === "rejected") {
        console.error(`Failed to teardown workspace ${agentNames[index]}:`, result.reason);
        teardownFailed = true;
      } else if (result.value.error) {
        console.error(`Failed to teardown workspace ${agentNames[index]}:`, result.value.error);
        teardownFailed = true;
      } else {
        console.log(`Successfully tore down workspace ${agentNames[index]}`);
      }
    });

    if (teardownFailed) {
      // If we got here but teardown failed, we should probably still exit non-zero
      // but the requirement says exit 0 on success. If initialization succeeded but teardown failed,
      // is it a success? Usually yes for the task, but let's be safe.
    }
  }
}

main().then(() => {
    process.exit(0);
}).catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});

